// O layout binario tem que bater com o sizeof() do Delphi: essas
// structs viajam na rede e vao para o banco.
func TestGeneratedSizesMatchDelphi(t *testing.T) {
	for _, c := range genCases() {
		if got := binary.Size(c.v); got != c.want {
			t.Errorf("%s: %d bytes, o Delphi tem %d", c.name, got, c.want)
		}
	}
}

// binary.Size nao exercita a reflexao de escrita: um campo de
// padding com nome nao exportado diferente de "_" faz binary.Read
// entrar em panico. Este teste decodifica e recodifica cada struct
// para pegar isso.
func TestGeneratedRoundTrip(t *testing.T) {
	for _, c := range genCases() {
		size := binary.Size(c.v)
		buf := make([]byte, size)
		for i := range buf {
			buf[i] = byte(i*31 + 7)
		}
		ptr := reflect.New(reflect.TypeOf(c.v))
		if err := binary.Read(bytes.NewReader(buf), binary.LittleEndian, ptr.Interface()); err != nil {
			t.Errorf("%s: Read: %v", c.name, err)
			continue
		}
		var out bytes.Buffer
		if err := binary.Write(&out, binary.LittleEndian, ptr.Elem().Interface()); err != nil {
			t.Errorf("%s: Write: %v", c.name, err)
			continue
		}
		if out.Len() != size {
			t.Errorf("%s: recodificou %d bytes, queria %d", c.name, out.Len(), size)
			continue
		}
		// Sem padding o conteudo tem que voltar identico. Com padding os
		// bytes de alinhamento voltam zerados, entao so o tamanho vale.
		if !c.hasPad && !bytes.Equal(out.Bytes(), buf) {
			t.Errorf("%s: ida e volta mudou o conteudo", c.name)
		}
	}
}
